package com.bank.thissuper.model;

import java.math.BigDecimal;

public class Account {
    private final String accountId;
    private final String holderName;
    protected BigDecimal balance;
    protected String description = "Generic Account";

    // Primary constructor:
    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;    // this.accountId = field, accountId = parameter
        this.holderName = holderName;
        this.balance = balance;
    }

    // Convenience: chains to primary using this()
    public Account(String accountId, String holderName) {
        this(accountId, holderName, BigDecimal.ZERO);  // this() — first statement!
    }

    public void withdraw(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) {
            throw new IllegalStateException("Insufficient: Rs." + balance + " for Rs." + amount);
        }
        balance = balance.subtract(amount);
    }

    public String describe() {
        return description + " [" + accountId + "]";
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public String getDescription() { return description; }
}
