// ─── File: src/main/java/com/bank/thissuper/model/SavingsAccount.java ───
package com.bank.thissuper.model;

import java.math.BigDecimal;

public class SavingsAccount extends Account {
    private static final BigDecimal MIN_BALANCE = new BigDecimal("1000");
    private final BigDecimal interestRate;
    protected String description = "Savings Account";  // SHADOWS Account.description!

    // Constructor calls super() — parent constructor:
    public SavingsAccount(String accountId, String holderName, BigDecimal balance, BigDecimal rate) {
        super(accountId, holderName, balance);  // super() — MUST be first statement!
        this.interestRate = rate;
    }

    // Convenience: chains to THIS class constructor using this():
    public SavingsAccount(String accountId, String holderName) {
        this(accountId, holderName, BigDecimal.ZERO, new BigDecimal("0.04"));
        // this() — calls the 4-arg constructor above. MUST be first statement!
    }

    // ═══ super.withdraw() — calls parent's version, then adds our check ═══
    @Override
    public void withdraw(BigDecimal amount) {
        // OUR extra check: minimum balance
        if (balance.subtract(amount).compareTo(MIN_BALANCE) < 0) {
            throw new IllegalStateException(
                "Savings must keep Rs." + MIN_BALANCE + " minimum. Balance: Rs." + balance);
        }
        super.withdraw(amount);  // super.withdraw() — reuses Account's debit logic!
        // Without super: we'd have to duplicate "balance = balance.subtract(amount)"
    }

    // ═══ this.description vs super.description — field shadowing ═══
    public String getThisDescription() {
        return this.description;   // "Savings Account" — THIS class's field
    }

    public String getSuperDescription() {
        return super.description;  // "Generic Account" — PARENT class's field
    }

    @Override
    public String describe() {
        return this.description + " (parent says: " + super.description + ") [" + getAccountId() + "]";
    }

    // ═══ this as object reference ═══
    public SavingsAccount getSelf() {
        return this;  // returns the current object itself
    }

    public BigDecimal getInterestRate() { return interestRate; }
}
```

